finetuning.file:
#!/bin/sh
# Telezart in-guest statistics for the boot trace.
# Counts everything from /root/telezart-trace-boot.txt and writes
# the ledger to /root/telezart-stats.txt. Pointer matching joins
# each free to its allocation; the pointers in ftrace output are
# the kernel's hashed tokens, consistent within one boot, which
# is all the matching needs.
T=/root/telezart-trace-boot.txt
S=/root/telezart-stats.txt
[ -f "$T" ] || { echo "no trace at $T"; exit 1; }
awk '
function bucket(b){ return (b<=64?"le64":b<=256?"b65_256":b<=1024?"b257_1024":b<=8192?"b1025_8192":"gt8192") }
{
  ev=""; ptr=""; br=-1; ba=-1;
  for(i=1;i<=NF;i++){
    if($i=="kmalloc:"||$i=="kmem_cache_alloc:"){ ev="alloc"; fam=$i }
    else if($i=="kfree:"||$i=="kmem_cache_free:"){ ev="free"; fam=$i }
    else if($i ~ /^ptr=/){ split($i,a,"="); ptr=a[2] }
    else if($i ~ /^bytes_req=/){ split($i,a,"="); br=a[2] }
    else if($i ~ /^bytes_alloc=/){ split($i,a,"="); ba=a[2] }
  }
  if(ev==""){ next }
  cnt[fam]++
  if(ev=="alloc"){
    nalloc++; sreq+=br; salloc+=ba; if(br>maxreq) maxreq=br;
    h[bucket(br)]++;
    if(ptr in live){ replaced++; livebytes-=live[ptr] } else { nlive++ }
    live[ptr]=br; g_live[ptr]=ba; livebytes+=br;
    if(livebytes>peakbytes) peakbytes=livebytes;
    if(nlive>peakobjs) peakobjs=nlive;
  } else {
    if(ptr in live){
      freedreq+=live[ptr]; freedalloc+=g_live[ptr];
      livebytes-=live[ptr]; delete live[ptr]; delete g_live[ptr];
      nlive--; nfreematched++;
    } else nfreeunmatched++;
  }
}
END{
  MiB=1048576;
  printf "Telezart boot trace ledger\n";
  printf "events kmalloc %d kmem_cache_alloc %d kfree %d kmem_cache_free %d\n", cnt["kmalloc:"], cnt["kmem_cache_alloc:"], cnt["kfree:"], cnt["kmem_cache_free:"];
  printf "allocations %d  sum_req %d bytes (%.2f MiB)  sum_alloc %d bytes (%.2f MiB)  max_req %d\n", nalloc, sreq, sreq/MiB, salloc, salloc/MiB, maxreq;
  printf "frees matched %d  freed_req %d bytes (%.2f MiB)  freed_alloc %d bytes (%.2f MiB)\n", nfreematched, freedreq, freedreq/MiB, freedalloc, freedalloc/MiB;
  printf "frees unmatched (pre-window objects) %d  replaced-pointer allocs %d\n", nfreeunmatched, replaced;
  printf "difference req %.2f MiB  alloc %.2f MiB\n", (sreq-freedreq)/MiB, (salloc-freedalloc)/MiB;
  printf "peak live %d bytes (%.2f MiB) in %d objects\n", peakbytes, peakbytes/MiB, peakobjs;
  printf "live at end %d bytes (%.2f MiB) in %d objects\n", livebytes, livebytes/MiB, nlive;
  printf "histogram le64 %d  65-256 %d  257-1024 %d  1025-8192 %d  gt8192 %d\n", h["le64"], h["b65_256"], h["b257_1024"], h["b1025_8192"], h["gt8192"];
}' "$T" > "$S"
# Percentiles of bytes_req: sort the request sizes once.
grep -o 'bytes_req=[0-9]*' "$T" | cut -d= -f2 | sort -n > /tmp/telezart-sizes.txt
N=$(wc -l < /tmp/telezart-sizes.txt)
if [ "$N" -gt 0 ]; then
  for P in 20 50 80; do
    R=$(( (N * P + 99) / 100 )); [ "$R" -lt 1 ] && R=1
    V=$(sed -n "${R}p" /tmp/telezart-sizes.txt)
    echo "P${P} bytes_req $V" >> "$S"
  done
fi
rm -f /tmp/telezart-sizes.txt
echo "stats written to $S"
